import {AbsoluteFill} from 'remotion';
import {ActRoot, KitProvider, LogoBuild, useFilmTime, useTokens, useFrameSize, easeNamed, dur} from '@slate/kit';

function Panel({dark}: {dark: boolean}) {
  const tk = useTokens();
  const t = useFilmTime();
  const {width, height} = useFrameSize();
  const entry = easeNamed('arrive')(Math.max(0, Math.min(1, (t - 5.5) / dur('base'))));
  const color = dark ? tk.color.onInverse : tk.color.ink;
  return <AbsoluteFill style={{background: dark ? tk.color.inverse : tk.color.page, color, fontFamily: 'Public Sans'}}>
    <div style={{position:'absolute',top:height*.07,left:width*.1,fontSize:height*.024,letterSpacing:2,fontWeight:700}}>{dark ? 'B / HARBOUR' : 'A / WARM STONE'}</div>
    <LogoBuild logo={dark ? 'mark-inverse' : 'mark'} dark={dark} t0={.7} x={width*.31} y={height*.36} w={width*.38} settleBy={5.4}/>
    <div style={{position:'absolute',top:height*.73,left:0,right:0,textAlign:'center',opacity:entry,transform:"'`translateY(${(1-entry)*12}px)`}}>
      <div style={{fontSize:height*.058,fontWeight:700,letterSpacing:-1}}>Demo Studio</div>
      <div style={{fontSize:height*.029,marginTop:height*.017}}>Start here</div>
    </div>
    <div style={{position:'"'absolute',bottom:height*.045,left:0,right:0,textAlign:'center',fontSize:height*.019}}>PREPRODUCTION LOOK STUDY · FICTIONAL DEMO BRAND</div>
  </AbsoluteFill>;
}
function Scene(){
  const {width,height}=useFrameSize();
  return <AbsoluteFill>{[false,true].map((dark,i)=><div key={i} style={{position:'absolute',left:i*width/2,top:0,width:width/2,height,overflow:'hidden'}}><KitProvider width={width/2} height={height}><Panel dark={dark}/></KitProvider></div>)}</AbsoluteFill>;
}
export default function Act1({sub}:{sub:number}) { return <ActRoot act={1} sub={sub}><Scene/></ActRoot>; }
''')
(p/'scenes/act1/NOTES.md').write_text('''# Preproduction look study

This is a standalone 12-second comparison for review, not a main-film act. Both panels use the demo pack’s exact SVG colourways, palette, Public Sans and the shared kit’s LogoBuild. Labels distinguish the two grounds. A is proposed; neither is approved. Timing is provisional and has no voice. The final film’s one keystone build is previewed once per comparison panel here.

